import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"1963年 · 复利为王","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1963年.md","filePath":"05_quotes/by-year/1963年.md"}'),l={name:"05_quotes/by-year/1963年.md"};function s(u,e,q,_,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1963年-·-复利为王" tabindex="-1">1963年 · 复利为王 <a class="header-anchor" href="#_1963年-·-复利为王" aria-label="Permalink to &quot;1963年 · 复利为王&quot;">​</a></h1><blockquote><p>&quot;我认为，道指未来数十年难以维持过去七年的复利水平，且我们相对道指的超额收益也无法保持当前水准。&quot;——巴菲特（33岁）</p></blockquote><p>本页收录1963年致股东信中的经典语录。巴菲特以达·芬奇《蒙娜丽莎》的故事辛辣讽刺了艺术品投资的荒谬，系统论证了复利的魔力，并再次强调：投资需要耐心，至少三年的检验周期是绝对底线。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;道指下跌25%、我们下跌15%的年份，远比我们和道指都上涨20%的年份要成功得多。&quot;</p></blockquote><blockquote><p>&quot;我再次强调：量化是基础且必要，质化同样重要。我们青睐优质管理层、良好行业，以及沉寂管理层或股东群体的&#39;变革潜力&#39;，但<strong>价值是底线</strong>。&quot;</p></blockquote><blockquote><p>&quot;控股项目必有保底利润，核心是收购价格足够低。获得控制权后，投资价值由企业价值决定，而非市场的非理性波动。&quot;</p></blockquote><blockquote><p>&quot;登普斯特的故事启示：我们的业务需要耐心，与热门高价股组合截然不同。业绩需按足够周期衡量，我们建议<strong>至少三年</strong>。&quot;</p></blockquote><blockquote><p>&quot;如果我们不谈论当前投资操作，是因为公开信息绝不会提升业绩，某些情况下还会严重损害利益。&quot;</p></blockquote><blockquote><p>&quot;我认为，道指未来数十年难以维持过去七年的复利水平，且我们相对道指的超额收益也无法保持当前水准。基于这些假设，合伙公司未来年均复利收益率将显著低于过往。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1963年道指上涨20.7%，合伙企业整体收益达38.7%，年化复合收益率27.7%（有限合伙人22.3%）。巴菲特在信中首次详细介绍了德州国家石油公司的套利案例，并成功完成了登普斯特的资产出售，以每股约80美元的总价值让合伙人获得丰厚回报。合伙企业净资产已达1700万美元。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1963年-翻译-·-01-letters-1963年-核心总结-·-01-letters-1963年-思维导图" tabindex="-1"><a href="/01_letters/1963年/翻译">01_letters/1963年/翻译</a> · <a href="/01_letters/1963年/核心总结">01_letters/1963年/核心总结</a> · <a href="/01_letters/1963年/思维导图">01_letters/1963年/思维导图</a> <a class="header-anchor" href="#_01-letters-1963年-翻译-·-01-letters-1963年-核心总结-·-01-letters-1963年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1963年/翻译]] · [[→ 核心总结|01_letters/1963年/核心总结]] · [[→ 思维导图|01_letters/1963年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1963年/翻译">/01_letters/1963年/翻译</a></li></ul>',19)])])}const b=t(l,[["render",s]]);export{i as __pageData,b as default};
